CREATE TABLE DATA.t_cats_rate_overview_2 (
client_id 							NUMBER(38,0) 	NOT NULL 	COMMENT 'Client id - calculated based on the country_2 code', 
country_cd							VARCHAR(5)		NULL 	 	COMMENT 'Country_2 code (two digits). Original name: Country_2',
rdc                                 VARCHAR(512)	NULL 	 	COMMENT 'Company name',
distribution_center                 VARCHAR(5)		NULL 	 	COMMENT 'Company code (three digits)',
carrier_name                        VARCHAR(512)	NULL 	 	COMMENT 'Full carrier name',
carrier_id                          VARCHAR(512)	NULL 	 	COMMENT 'Unique forwarding ID; corresponds to the Business Partner ID from SAP',
valid_from                          DATE			NULL 	 	COMMENT 'Validity_2 start date of the contract version or the conditions',
valid_until							DATE			NULL 	 	COMMENT 'Validity_2 end date of the contract version or the conditions', 
number_of_trucks                    FLOAT			NULL 	 	COMMENT 'Number of trucks available',
currency                            VARCHAR(512)	NULL 	 	COMMENT 'National currency (abbreviation, three digits)',
exchange_rate                       FLOAT			NULL 	 	COMMENT 'Exchange rate from euros to local currency',
resource_type                       VARCHAR(512)	NULL 	 	COMMENT 'Vehicle type with which the tour_2 is carried out (e.g. articulated truck) (data from Quintiq)',
fuel_type                           VARCHAR(512)	NULL 	 	COMMENT 'Type of drive that is negotiated and stored in the contract',
shift                               VARCHAR(512)	NULL 	 	COMMENT 'Shift of a day on which the conditions per shift are valid (single digit)',
weekday                             VARCHAR(512)	NULL 	 	COMMENT 'Days of the week on which the conditions are valid are listed, separated by commas',
resource_technique                  VARCHAR(512)	NULL 	 	COMMENT 'Vehicle technology with which the tour_2 is carried out (e.g. mono- / bi-temp) (data from Quintiq)',
truck_code                          VARCHAR(512)	NULL 	 	COMMENT 'Truck code',
means_of_transport                  VARCHAR(512)	NULL 	 	COMMENT 'Transport resource for which the conditions are valid (INT definition of individual vehicle resources, data from Quintiq) (e.g. tractor or trailer)',
other_rules                         VARCHAR(2048)	NULL 	 	COMMENT 'Other conditions that can be linked to the conditions for each freight forwarder',
fixed_costs_shift                   FLOAT			NULL 	 	COMMENT 'Condition per shift',
toll                                FLOAT			NULL 	 	COMMENT 'Multiplier of the toll costs from Quintiq (for transfer to CATS)',
toll_costs_per_km                   FLOAT			NULL 	 	COMMENT 'Condition per toll kilometer',
fixed_costs_oneway                  FLOAT			NULL 	 	COMMENT 'Condition per route',
fixed_costs_day                     FLOAT			NULL 	 	COMMENT 'Condition per day',
fixed_costs_tour                    FLOAT			NULL 	 	COMMENT 'Condition per tour_2',
fixed_costs_predefined_tour         FLOAT			NULL 	 	COMMENT 'Condition per predefined tour_2',
variable_costs_per_km               FLOAT			NULL 	 	COMMENT 'Condition per kilometer',
variable_costs_per_hour             FLOAT			NULL 	 	COMMENT 'Condition per hour',
surcharge_per_stop_1                FLOAT			NULL 	 	COMMENT 'Surcharge for first stop',
surcharge_per_stop_2                FLOAT			NULL 	 	COMMENT 'Surcharge for second stop',
surcharge_per_stop_3                FLOAT			NULL 	 	COMMENT 'Surcharge for third stop',
surcharge_sunday                    FLOAT			NULL 	 	COMMENT 'Surcharge for transport on Sunday delivery day',
surcharge_taillift                  FLOAT			NULL 	 	COMMENT 'Surcharge when using a tail lift',
surcharge_frozen_goods              FLOAT			NULL 	 	COMMENT 'Surcharge for frozen shipments',
floater                             FLOAT			NULL 	 	COMMENT 'Base price for calculating the floater',
special_floater                     FLOAT			NULL 	 	COMMENT 'Base price for calculating the floater (country_2-specific logic for calculation stored in CATS)',
fixed_costs_pallet                  FLOAT			NULL 	 	COMMENT 'Condition per pallet',
fixed_costs_km_range                FLOAT			NULL 	 	COMMENT 'Country_2-specific definition of the condition',
special_truck                       FLOAT			NULL 	 	COMMENT 'Country_2-specific definition of the condition',
surcharge_saturday                  FLOAT			NULL 	 	COMMENT 'Country_2-specific definition of the condition (usually surcharge for delivery day on a Saturday)',
surcharge_holiday                   FLOAT			NULL 	 	COMMENT 'Country_2-specific definition of the condition (usually surcharge for delivery day on a national holiday)',
costs_extended_shift                FLOAT			NULL 	 	COMMENT 'Country_2-specific definition of the condition',
surcharge_tour                      FLOAT			NULL 	 	COMMENT 'Country_2-specific definition of the condition',
surcharge_overtime                  FLOAT			NULL 	 	COMMENT 'Country_2-specific definition of the condition',
surcharge_flexibility               FLOAT			NULL 	 	COMMENT 'Country_2-specific definition of the condition',
surcharge_night                     FLOAT			NULL 	 	COMMENT 'Country_2-specific definition of the condition',
surcharge_store                     FLOAT			NULL 	 	COMMENT 'Country_2-specific definition of the condition',
surcharge_special_store             FLOAT			NULL 	 	COMMENT 'Country_2-specific definition of the condition',
surcharge_city                      FLOAT			NULL 	 	COMMENT 'Country_2-specific definition of the condition',
city_taxes                          FLOAT			NULL 	 	COMMENT 'Country_2-specific definition of the condition',
stationing                          FLOAT			NULL 	 	COMMENT 'Country_2-specific definition of the condition',
ferries                             FLOAT			NULL 	 	COMMENT 'Country_2-specific definition of the condition',
surcharge_cancellation              FLOAT			NULL 	 	COMMENT 'Country_2-specific definition of the condition',
trailer_hire                        FLOAT			NULL 	 	COMMENT 'Country_2-specific definition of the condition',
empty_trailer                       FLOAT			NULL 	 	COMMENT 'Country_2-specific definition of the condition',
surcharge_fuel                      FLOAT			NULL 	 	COMMENT 'Country_2-specific definition of the condition',
waste_return                        FLOAT			NULL 	 	COMMENT 'Country_2-specific definition of the condition',
waste_return_floater                FLOAT			NULL 	 	COMMENT 'Country_2-specific definition of the condition',
additional_drops                    FLOAT			NULL 	 	COMMENT 'Country_2-specific definition of the condition',
discount_self_pickup                FLOAT			NULL 	 	COMMENT 'Country_2-specific definition of the condition',
LOADING                             FLOAT			NULL 	 	COMMENT 'Country_2-specific definition of the condition',
pre_loading                         FLOAT			NULL 	 	COMMENT 'Country_2-specific definition of the condition',
surcharge_e_trailer                 FLOAT			NULL 	 	COMMENT 'Country_2-specific definition of the condition',
consumption                         FLOAT			NULL 	 	COMMENT 'Country_2-specific definition of the condition (mostly negotiated consumption)',
dwh_load_id    						NUMBER(38,0) 	NOT NULL 	COMMENT 'Load id',
dwh_created    						TIMESTAMP 		NOT NULL 	COMMENT 'Record created at',
dwh_updated    						TIMESTAMP 		NOT NULL 	COMMENT 'Record updated at'
) COMMENT = 'CATS - overview of all conditions of one or even all freight forwarders in order to have a better basis for negotiations.';